CREATE TABLE public.quota_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),buyer_id uuid NOT NULL REFERENCES public.shareholders(id),seller_id uuid REFERENCES public.shareholders(id),amount numeric NOT NULL,quota_pct numeric NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.quota_operations TO authenticated; GRANT ALL ON public.quota_operations TO service_role; ALTER TABLE public.quota_operations ENABLE ROW LEVEL SECURITY; CREATE POLICY "partner quota history" ON public.quota_operations FOR SELECT TO authenticated USING(public.is_partner(auth.uid()));
CREATE FUNCTION public.add_shareholder(_name text,_email text,_contact text,_doc text,_amount numeric,_seller uuid,_quota numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE total numeric; sh uuid; seller public.shareholders; BEGIN IF NOT public.is_partner(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM pg_advisory_xact_lock(8521002); IF length(trim(_name))<2 OR _amount<=0 THEN RAISE EXCEPTION 'Nome e investimento positivo obrigatórios'; END IF; IF _seller IS NOT NULL THEN SELECT * INTO seller FROM public.shareholders WHERE id=_seller FOR UPDATE; IF seller.id IS NULL OR _quota<=0 OR _quota>seller.capital_pct THEN RAISE EXCEPTION 'Quota acima da participação do vendedor'; END IF; UPDATE public.shareholders SET capital_pct=capital_pct-_quota WHERE id=_seller; INSERT INTO public.shareholders(name,email,contact,doc_number,invested,capital_pct) VALUES(_name,_email,_contact,_doc,_amount,_quota) RETURNING id INTO sh; ELSE SELECT coalesce(sum(invested),0) INTO total FROM public.shareholders; IF total=0 AND EXISTS(SELECT 1 FROM public.shareholders) THEN RAISE EXCEPTION 'Registe o capital investido dos sócios existentes antes de aumentar capital'; END IF; UPDATE public.shareholders SET capital_pct=invested/(total+_amount)*100; INSERT INTO public.shareholders(name,email,contact,doc_number,invested,capital_pct) VALUES(_name,_email,_contact,_doc,_amount,_amount/(total+_amount)*100) RETURNING id INTO sh; END IF; INSERT INTO public.quota_operations(buyer_id,seller_id,amount,quota_pct,actor_id) SELECT sh,_seller,_amount,capital_pct,auth.uid() FROM public.shareholders WHERE id=sh; RETURN sh; END $$;
CREATE TABLE public.reserve_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reserve_id uuid NOT NULL REFERENCES public.strategic_reserves(id),kind text NOT NULL,amount numeric NOT NULL,proof_path text NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.reserve_operations TO authenticated; GRANT ALL ON public.reserve_operations TO service_role; ALTER TABLE public.reserve_operations ENABLE ROW LEVEL SECURITY; CREATE POLICY "partner reserve history" ON public.reserve_operations FOR SELECT TO authenticated USING(public.is_partner(auth.uid()));
CREATE FUNCTION public.move_reserve(_id uuid,_kind text,_amount numeric,_proof text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.strategic_reserves; BEGIN IF NOT public.is_partner(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO r FROM public.strategic_reserves WHERE id=_id FOR UPDATE; IF r.id IS NULL OR _amount<=0 OR _kind NOT IN ('reforco','uso') OR (_kind='uso' AND _amount>r.balance) THEN RAISE EXCEPTION 'Movimento inválido'; END IF; IF r.kind='nao_recorrente' AND _kind='reforco' AND r.balance+_amount>r.target THEN RAISE EXCEPTION 'Meta da reserva excedida'; END IF; IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='comprovativos' AND name=_proof AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Comprovativo obrigatório'; END IF; UPDATE public.strategic_reserves SET balance=balance+CASE WHEN _kind='reforco' THEN _amount ELSE -_amount END WHERE id=_id; INSERT INTO public.reserve_operations(reserve_id,kind,amount,proof_path,actor_id) VALUES(_id,_kind,_amount,_proof,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.add_shareholder(text,text,text,text,numeric,uuid,numeric),public.move_reserve(uuid,text,numeric,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.add_shareholder(text,text,text,text,numeric,uuid,numeric),public.move_reserve(uuid,text,numeric,text) TO authenticated;
CREATE TABLE public.debt_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),debt_id uuid NOT NULL REFERENCES public.debts(id),name text NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),unit text NOT NULL DEFAULT 'un',unit_price numeric NOT NULL CHECK(unit_price>=0),group_name text); GRANT SELECT,INSERT,UPDATE,DELETE ON public.debt_items TO authenticated; GRANT ALL ON public.debt_items TO service_role; ALTER TABLE public.debt_items ENABLE ROW LEVEL SECURITY; CREATE POLICY "finance debt items" ON public.debt_items FOR ALL TO authenticated USING(public.area_access(auth.uid(),'financas')) WITH CHECK(public.area_access(auth.uid(),'financas'));
CREATE FUNCTION public.validate_vacation_balance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.employees; months integer; acc numeric; used numeric; BEGIN SELECT * INTO e FROM public.employees WHERE id=NEW.employee_id FOR UPDATE; months:=greatest(0,(extract(year FROM age(CURRENT_DATE,e.hire_date))*12+extract(month FROM age(CURRENT_DATE,e.hire_date)))::integer); acc:=CASE WHEN e.contract_type='determinado' THEN months ELSE least(months,12)+greatest(0,months-12)*2.5 END; SELECT coalesce(sum(days),0) INTO used FROM public.vacations WHERE employee_id=e.id AND id<>NEW.id; IF NEW.days<=0 OR NEW.days>acc-used THEN RAISE EXCEPTION 'Férias acima do saldo disponível'; END IF; RETURN NEW; END $$; CREATE TRIGGER vacation_balance BEFORE INSERT OR UPDATE ON public.vacations FOR EACH ROW EXECUTE FUNCTION public.validate_vacation_balance();